class Dog:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return f"{self.name} barks"
print(Dog("Rex").speak())

class A:
    def hi(self): return "A"
class B(A):
    def hi(self): return super().hi() + "B"
print(B().hi())

class V:
    def __init__(s, x): s.x = x
    def __add__(s, o): return V(s.x + o.x)
    def __repr__(s): return f"V({s.x})"
print(V(1) + V(2))

def twice(f):
    def w(*a): return f(f(*a))
    return w
@twice
def inc(x): return x + 1
print(inc(1))

from dataclasses import dataclass
@dataclass
class P:
    x: int
    y: int = 0
print(P(1), P(1) == P(1))

def greet(n: str, times: int = 1) -> str:
    return n * times
print(greet("ab", 2))

from functools import lru_cache, reduce
@lru_cache
def fib(n): return n if n < 2 else fib(n-1) + fib(n-2)
print(fib(50), reduce(lambda a, b: a * b, [1, 2, 3, 4]))

class T:
    def __enter__(s): print("in"); return s
    def __exit__(s, *e): print("out")
with T(): print("body")

class C:
    __slots__ = ("_x",)
    def __init__(s): s._x = 1
    @property
    def x(s): return s._x
print(C().x)

class Meta(type):
    def __new__(m, n, b, d):
        d["tag"] = n
        return super().__new__(m, n, b, d)
class K(metaclass=Meta): pass
print(K.tag)
